class NDXDeleteNotificationsService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// PaffH 07.06.21
/// delete notifications for a user for a period
/// </summary>
/// <param name = "_contract">NDXDeleteNotificationsContract</param>
public void processOperation(NDXDeleteNotificationsContract _contract)
{
    info(strFmt("@NDX:NDXDeleteNotificationsStart", NDXHelperCommon::seconds2Str()));
    Info(strFmt("@NDX:NDXDeleteNotificationsForUserForPeriod", _contract.parmUserId(), _contract.parmUtcDateTimeFrom(), _contract.parmUtcDateTimeTo()));
    SystemNotificationsManager systemNotificationsManager = new SystemNotificationsManager();
    int notifications2Delete = systemNotificationsManager.GetNotificationsFromContract(_contract).elements();
    info(strFmt("@NDX:NDXNotificationsDetected", NDXHelperCommon::seconds2Str(), notifications2Delete));
    int notificationsDeleted = systemNotificationsManager.DeleteNotificationsFromContract(_contract);
    info(strFmt("@NDX:NDXDeleteNotificationsEnd", NDXHelperCommon::seconds2Str(), notificationsDeleted));
}
